    term.write_line(&prompt.question).map_err(BivvyError::Io)?;
    term.hide_cursor().map_err(BivvyError::Io)?;

    loop {
        // Draw option lines
        for (i, opt) in options.iter().enumerate() {
            let line = if i == sel {
                format!(
                    "{}{} {}",
                    pad,
                    active_prefix.apply_to("›"),
                    active_style.apply_to(&opt.label)
